import {createPayState,methods,registerPayMember,configureMerchant,pointBalance,payTransaction,settlePayCompensation} from './member-pay-state.mjs';
const s=createPayState(),$=x=>document.querySelector(x),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>(n/100).toFixed(2),currency={CNY:'人民币',JPY:'日元',USD:'美元'};
const options=(rows,label)=>rows.map(x=>`<option value="${esc(x.id)}">${esc(label(x))}</option>`).join('');
const table=(head,rows)=>`<div class="table-wrap"><table><thead><tr>${head.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${head.length}">暂无记录</td></tr>`}</tbody></table></div>`;
let toastTimer;function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').style.display='block';toastTimer=setTimeout(()=>$('#toast').style.display='none',5000)}
function selectedMerchant(){return s.merchants.find(m=>m.id===$('#pay-merchant').value)}
function quote(){const m=selectedMerchant(),f=$('#pay-form'),amount=Number(f.amount.value),redeem=Number(f.redeem.value),balance=pointBalance(s,f.member.value,m.currency,m.country);$('#quote').textContent=`${m.country} · ${currency[m.currency]}独立账本。可用 ${fmt(balance)} 积分；拟抵扣 ${Number.isFinite(redeem)?redeem.toFixed(2):'—'} ${m.currency}，余款 ${Number.isFinite(amount-redeem)?Math.max(0,amount-redeem).toFixed(2):'—'} ${m.currency}。消费奖励 ${m.consumerRate}%，一级推荐 ${m.referralRate}%，只对实付余款计奖。`;f.amount.step=f.redeem.step=m.currency==='JPY'?'1':'0.01'}
function changeMerchant(){const m=selectedMerchant();$('#pay-method').innerHTML=m.methods.map(x=>`<option>${esc(x)}</option>`).join('');$('#identified').textContent='模拟扫码尚未识别；选择会员后可直接登记，真实扫码待接入。';quote()}
function settings(){const m=s.merchants.find(x=>x.id===$('#settings-merchant').value),f=$('#settings-form');f.consumerRate.value=m.consumerRate;f.referralRate.value=m.referralRate;$('#methods').innerHTML=methods.map(x=>{const disabled=x.includes('现金')&&x!==({CNY:'人民币现金',JPY:'日元现金',USD:'美元现金'}[m.currency]);return `<label><input type="checkbox" name="methods" value="${esc(x)}" ${m.methods.includes(x)?'checked':''} ${disabled?'disabled':''}>${esc(x)}</label>`}).join('');$('#merchant-budget').textContent=`国家：${m.country}；币种：${m.currency}；剩余模拟营销额度：${fmt(m.budget)} ${m.currency}。奖励从此额度扣除，实际资金未接入。`}
function render(){const chosen=$('#pay-member').value,inviter=$('#inviter').value;$('#pay-member').innerHTML=s.members.length?options(s.members,m=>m.id+' · '+m.name):'<option value="">请先注册会员</option>';if(s.members.some(m=>m.id===chosen))$('#pay-member').value=chosen;$('#inviter').innerHTML='<option value="">无推荐人</option>'+options(s.members,m=>m.id+' · '+m.name);$('#inviter').value=inviter;$('#member-list').innerHTML=s.members.map(m=>`<div class="member"><b>${esc(m.id)} · ${esc(m.name)}</b><br>直接推荐人：${esc(m.inviter||'无')} · 已直接邀请 ${s.members.filter(x=>x.inviter===m.id).length} 人</div>`).join('');$('#metrics').innerHTML=[['独立模拟会员',s.members.length+' 人'],['已登记消费',s.orders.length+' 笔'],['待跨店补偿',s.settlements.filter(x=>x.status==='待补偿').length+' 笔']].map(([label,value])=>`<div class="metric">${label}<strong>${value}</strong></div>`).join('');$('#point-ledger').innerHTML=table(['会员ID','发行 / 责任商户','币种','类型','原始积分','剩余可用积分'],s.lots.map(l=>[l.memberId,esc(s.merchants.find(m=>m.id===l.issuer).name),l.currency,l.kind,fmt(l.original),fmt(l.remaining)]));$('#settlement-list').innerHTML=table(['补偿编号','原发分商户 → 接受商户','金额','状态','处理'],s.settlements.map(r=>[r.id,r.from+' → '+r.to,fmt(r.amount)+' '+r.currency,r.status,r.status==='待补偿'?`<button data-settle="${r.id}">标记模拟补偿</button>`:'不可重复补偿']));$('#orders').innerHTML=table(['成交编号','会员','商户','账单','积分抵扣','实付 / 方式','消费奖励','推荐奖励 / 接收人'],s.orders.map(o=>[esc(o.reference),o.memberId,o.merchantId,fmt(o.amount)+' '+o.currency,fmt(o.redeem),fmt(o.payable)+' '+o.currency+' / '+esc(o.method),fmt(o.consumer),fmt(o.referral)+' / '+(o.inviter||'无')]));quote();settings()}
$('#pay-merchant').innerHTML=$('#settings-merchant').innerHTML=options(s.merchants,m=>m.name+' · '+m.currency);
$('#pay-reference').value='DEMO-'+crypto.randomUUID();$('#pay-merchant').onchange=changeMerchant;$('#pay-member').onchange=quote;$('#settings-merchant').onchange=settings;$('#pay-form').addEventListener('input',quote);
$('#member-form').onsubmit=e=>{e.preventDefault();try{const f=e.target,m=registerPayMember(s,f.elements.namedItem('name').value,f.inviter.value);f.reset();render();$('#pay-member').value=m.id;quote();toast('独立会员ID已生成：'+m.id)}catch(err){toast(err.message)}};
$('#scan-member').onclick=()=>{const m=s.members.find(x=>x.id===$('#pay-member').value);if(!m)return toast('请先注册会员并选择ID');$('#identified').textContent='模拟识别成功：'+m.id+' · '+m.name+'；推荐人：'+(m.inviter||'无')};
$('#settings-form').onsubmit=e=>{e.preventDefault();try{const f=e.target;configureMerchant(s,f.merchant.value,{consumerRate:Number(f.consumerRate.value),referralRate:Number(f.referralRate.value),methods:[...f.querySelectorAll('[name=methods]:checked')].map(x=>x.value)});changeMerchant();render();toast('商户模拟设置已保存，仅影响后续成交')}catch(err){toast(err.message)}};
$('#pay-form').onsubmit=e=>{e.preventDefault();try{const f=e.target,o=payTransaction(s,{merchantId:f.merchant.value,memberId:f.member.value,amount:Number(f.amount.value),redeem:Number(f.redeem.value),method:f.elements.namedItem('method').value,reference:f.reference.value,confirmed:f.confirmed.checked});f.confirmed.checked=false;f.redeem.value='0';f.reference.value='DEMO-'+crypto.randomUUID();render();toast(`模拟成交 ${o.id} 已登记，积分按发行商户记账；未扣真实资金`)}catch(err){toast(err.message)}};
document.addEventListener('click',e=>{const b=e.target.closest('[data-settle]');if(!b)return;try{settlePayCompensation(s,b.dataset.settle);render();toast('仅标记模拟补偿，未划转资金')}catch(err){toast(err.message)}});
changeMerchant();render();
